-- Generated by forever_tools.embed. Runs the addon's files, in TOC order, once ForeverCore is ready.
-- With ForeverCore already running (the standalone loaded first, or a load-on-demand host joining a running copy)
-- OnReady calls back at once, inside this file's load: the files run where they always did. Otherwise they run at
-- activation. Either way each frame they registered gets the loading events this addon already missed, once: its
-- ADDON_LOADED, PLAYER_LOGIN, and the first PLAYER_ENTERING_WORLD with its arguments.
local addon, host = ...
local chunks = host.ForeverCoreHostChunks or {}
host.ForeverCoreHostChunks = nil
-- The files the package wraps. The client loads no file that is new since it started, so an update made while the
-- game runs can leave one out: the addon's require gate (ns.ForeverRequire) then stops it with its line, where a
-- later file would have indexed what the missing one defines.
if #chunks ~= 90 then
	host.ForeverCoreHostIncomplete = true
end

local function Report(message)
	local handler = geterrorhandler and geterrorhandler()
	if handler then
		return handler(message)
	end
	return message
end

local EVENTS = { "ADDON_LOADED", "PLAYER_LOGIN", "PLAYER_ENTERING_WORLD" }

local function Registered(event)
	local set = {}
	if GetFramesRegisteredForEvent then
		for _, frame in ipairs({ GetFramesRegisteredForEvent(event) }) do
			set[frame] = true
		end
	end
	return set
end

-- Which of the loading events are already past for this addon's files. Run inline, the files load before this
-- addon's own ADDON_LOADED, so only an addon loaded after login has missed anything. Run at activation, this
-- addon's ADDON_LOADED and PLAYER_LOGIN are past, and the world entry is past when the loader saw it.
local function Missed(inline)
	local missed = {}
	local loader = ForeverCoreLoader
	local loggedIn = IsLoggedIn and IsLoggedIn()
	missed.ADDON_LOADED = not inline
	missed.PLAYER_LOGIN = not inline or loggedIn
	missed.PLAYER_ENTERING_WORLD = type(loader.Seen) == "function" and loader.Seen("PLAYER_ENTERING_WORLD") or false
	return missed
end

local function Deliver(missed, before)
	for _, event in ipairs(EVENTS) do
		if missed[event] then
			for frame in pairs(Registered(event)) do
				if not before[event][frame] then
					if event == "PLAYER_LOGIN" then
						-- PLAYER_LOGIN may still be dispatching: a frame added during it gets this one call only.
						frame:UnregisterEvent(event)
					end
					local script = frame:GetScript("OnEvent")
					if script then
						xpcall(function()
							if event == "ADDON_LOADED" then
								return script(frame, event, addon)
							elseif event == "PLAYER_ENTERING_WORLD" and ForeverCoreLoader.WorldEntry then
								return script(frame, event, ForeverCoreLoader.WorldEntry())
							end
							return script(frame, event)
						end, Report)
					end
				end
			end
		end
	end
end

local inline = true
ForeverCoreLoader.OnReady(function()
	-- The files run whether or not ForeverCore started: with no core, the addon's own require gate (Core/Require.lua)
	-- answers its slash words and compartment entry with the line naming the fix, and every later file stops on
	-- ns.broken, exactly as when no ForeverCore is installed at all.
	local runInline = inline
	local before = {}
	for _, event in ipairs(EVENTS) do
		before[event] = Registered(event)
	end
	-- Run at activation the client already counts this addon as loaded, so a file waiting for its own addon's load
	-- (ns.OnFilesLoaded) queues here and is called after the last file, as ADDON_LOADED would have called it.
	local after = {}
	if not runInline then
		host.ForeverCoreHostAfter = after
		-- For the rest of the session: these files ran at or after PLAYER_LOGIN (ns.AfterEvents).
		host.ForeverCoreHostDeferred = true
	end
	-- One file's error stops that file only, as the client's own file loading does.
	for index = 1, #chunks do
		xpcall(function()
			return chunks[index](addon, host)
		end, Report)
	end
	host.ForeverCoreHostAfter = nil
	for index = 1, #after do
		xpcall(after[index], Report)
	end
	local missed = Missed(runInline)
	if not runInline then
		return Deliver(missed, before)
	end
	if not (missed.PLAYER_LOGIN or missed.PLAYER_ENTERING_WORLD) then
		return
	end
	-- An addon loaded after login: its own ADDON_LOADED is still to come, so the events it missed follow it, on the
	-- next frame, in the client's order.
	local waiter = CreateFrame("Frame")
	waiter:RegisterEvent("ADDON_LOADED")
	waiter:SetScript("OnEvent", function(self, _, name)
		if name ~= addon then
			return
		end
		self:UnregisterEvent("ADDON_LOADED")
		local function deliver()
			Deliver(missed, before)
		end
		if C_Timer and C_Timer.After then
			C_Timer.After(0, deliver)
		else
			deliver()
		end
	end)
end)
inline = false
